CREATE TABLE `honda_faq` (
  `순번` int NOT NULL,
  `카테고리` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `질문` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `답변` text COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`순번`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
