LOCK TABLES `honda_faq` WRITE;
/*!40000 ALTER TABLE `honda_faq` DISABLE KEYS */;
INSERT INTO `honda_faq` VALUES (1,'서비스','서비스센터의 위치를 알고 싶습니다.','혼다코리아는 고객님들의 편의를 위해서 전국에 서비스센터를 운영하고 있습니다. 자세한 위치는 홈페이지 상단 메뉴의 \'서비스 → 서비스 네트워크\'에서 확인이 가능합니다.\n바로가기: HONDA (hondakorea.co.kr)'),(2,'서비스','서비스센터에 정비 예약을 하고 싶습니다.','차량관리 App \'My Honda\'를 통해서 쉽게 정비 예약이 가능합니다. My Honda App은 Google play store, App Store에서 다운로드가 가능합니다. 또한, 각 서비스센터에 유선연락을 통해서 예약을 하셔도 됩니다.\nMy Honda App 설명 및 다운르도: HONDA (hondakorea.co.kr)'),(3,'부품','부품 주문은 어떻게 하나요?','혼다코리아는 협력점을 포함하여 지정된 공식 딜러점을 통해서만 부품을 공급하고 있습니다.\n가장 가까운 서비스 센터에서 부품 구매 관련 상담을 받으시기 바랍니다.'),(4,'App','\'My Honda App\'은 무엇인가요?','혼다 차량을 구매하신 고객님들 위해서 차량 관리 및 정비 예약을 편리하게 할 수 있도록 서비스를 제공하는 App입니다. App을 통해서 차량을 등록하시면 정비 예약, 소모품 관리 주기 확인, 리콜 관리 안내 등 차량 관리에 꼭 필요한 기능을 이용할 수 있습니다.'),(5,'App','\'My Honda App\'을 통해서 정비 예약을 했습니다. 급한 사정으로 예약 날짜 변경 혹은 취소를 하고 싶은데 가능한가요?','\'My Honda App\'에서 정비 예약 날짜 변경 및 취소가 가능합니다. 단, 48시간 이내의 예약을 취소하고 싶다면 서비스센터에 직접 문의하셔야 합니다.'),(6,'App','\'My Honda App\'에서 \'교체 필요한 항목이 있습니다.\' 라는 메시지가 뜹니다. 어떻게 해야 하나요?','공식적으로 권장하는 제품 교체 주기에 따라서 \'교체 필요\', \'교체 검토\', \'양호\' 라는 3가지 상태로 구분이 됩니다.\n자세한 내용은 서비스센터를 통해서 안내를 받으시기 바랍니다.'),(7,'App','차량 명의가 배우자로 되어 있어서 제 휴대폰의 정보와 일치하지 않습니다. 차량 등록을 어떻게 해야 하나요?','차량 등록 시 하단에 차량등록증을 업로드 하시면 고객센터에서 확인 후 승인 처리를 도와드리고 있습니다.'),(8,'리콜','리콜 통지문을 받았습니다. 어떻게 해야하나요?','리콜은 고객님의 안전을 지키기 위한 중요한 조치이므로 가능한 빠르게 진행주시길 권장해드리고 있습니다.\n리콜 대상 여부 확인 후 인근 서비스센터로 유선 예약, 방문하여 진행해주시기 바랍니다.\n또는 My Honda App을 통해서 원하는 일자와 서비스센터, 리콜 진행을 선택하여 예약 신청이 가능합니다.'),(9,'리콜','리콜에 소요되는 시간은 얼마나 드나요?','리콜 종류에 따라서 소요되는 시간은 모두 다릅니다. 서비스센터를 통해서 소요 시간을 확인 부탁드립니다.'),(10,'구매','인도금 카드 결제는 삼성카드만 가능한가요?','네, 그렇습니다.\n고객님께 보다 더 많은 혜택을 제공해 드리고자 혼다코리아는 삼성카드와의 전략적 제휴를 맺게 되었습니다.\n계약금은 어떤 카드를 사용하셔도 상관없지만, 인도금을 카드로 지불 할 때에는 삼성카드로만 결제가 가능합니다.'),(11,'리콜','리콜 정비를 받는데 비용이 드나요?','리콜 정비를 받는데 별도의 비용은 들지 않습니다'),(12,'리콜','리콜 서비스는 반드시 받아야 하나요?','고객님들의 안전과 차량의 성능에 영향을 끼칠 수 있기 때문에 반드시 받으셔야 합니다.'),(13,'리콜','온라인을 통해서 리콜 확인을 할 수 있는 방법이 있나요?','자동차리콜센터를 통해 확인이 가능합니다. (www.car.go.kr)'),(14,'리콜','리콜을 받기 위해서 서비스센터를 예약하고 방문해야 하나요?','리콜 서비스를 받기 위해서는 사전에 서비스센터를 예약하고 방문하셔야 됩니다. \'My Honda App\' 또는 서비스센터에 전화로 예약 후 방문을 부탁드립니다.'),(15,'리콜','리콜 통지 이후 언제까지 리콜 서비스를 받아야 하나요?','정해진 기간은 없습니다. 다만, 고객님들의 안전과 직결된 부분이기 때문에 가급적 빠른 시일내에 받으시는 것을 추천드립니다.'),(16,'리콜','혼다코리아는 고객에게 리콜을 어떻게 통지하나요?','등록되어 있는 주소 및 휴대폰 번호를 기준으로 우편, SMS를 통하여 안내하고 있습니다.\n리콜을 통지 받지 못한 경우에는 연락처 확인을 위하여 혼다 고객센터(080-360-0505)나 가까운 서비스센터에 문의하십시오.'),(17,'리콜','차량을 구매했을 때와 지금 사는 곳의 주소가 다른데, 리콜 통지는 어디로 하나요?','구매했을 때의 주소가 아닌, 자동차 등록증에 기재된 주소로 발송됩니다.'),(18,'Honda Connect','\'Honda Connect\' 란 무엇인가요?','차량을 안심하고 쾌적하게 사용하기 위하여 자동차와 정보통신 기술을 융합한 모바일 어플리케이션입니다.'),(19,'Honda Connect','제공하는 기능은 무엇이 있나요?','고객님의 편의를 위하여 \'Honda Connect\'에서는 아래와 같이 다양한 기능을 제공하고 있습니다.\n1. 원격 기능 - 원격으로 문을 잠그고 열 수 있습니다.\n2. 차량 상태 확인 - 차량의 문 열림 상태나 남은 연료를 확인할 수 있습니다.\n3. 나의 차량 찾기 - 내 차량의 정확한 위치를 안내합니다.\n4. 경고 정보 수신 - 차량에 뜨는 경고 표시등 정보를 공유합니다.\n보다 자세한 내용은 서비스 센터 혹은 고객센터를 통하여 확인을 부탁드립니다.'),(20,'Honda Connect','모든 차량에서 사용을 할 수 있나요?','\'Honda Connect\'는 23년 이후에 출시된 차량에 대해서만 사용이 가능합니다.'),(21,'Honda Connect','서비스를 이용하는데 비용이 드나요?','신차 등록일부터 5년 동안은 무료로 이용하실 수 있습니다.\n이후, 비용에 대해서는 추후 안내드릴 수 있도록 하겠습니다.'),(22,'Honda Connect','어디에서 App을 다운로드 받을 수 있나요?','Google Play Store 또는 App Store에서 \'Honda Connect Korea\' 어플리케이션을 다운로드 받아 주세요.'),(23,'Honda Connect','병행수입을 한 차량에서도 이용이 가능한가요??','혼다코리아에서 공식 수입한 차량에 대해서만 이용이 가능합니다.');
/*!40000 ALTER TABLE `honda_faq` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `hyundai_faq`
