LOCK TABLES `volkswagen_faq` WRITE;
/*!40000 ALTER TABLE `volkswagen_faq` DISABLE KEYS */;
INSERT INTO `volkswagen_faq` VALUES (1,'경고등 & 알림','자주 묻는 경고등 정보','각종 경고등에 대한 정보는 사용자 매뉴얼이나 마이폭스바겐 경고등 안내 페이지를 확인 하세요.* My VW 앱 → 전체메뉴 → 경고등차량 경고등 확인하기* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(2,'경고등 & 알림','타이어 공기압 경고등이 떴는데 타이어 상태에 이상이 없는데 왜 그런가요?\n이 경우 타이어 공기압 경고등 리셋(재설정)은 어떻게 하나요?','타이어 공기압 경고등은 공기압이 설정된 기준치 보다 낮은 것으로 인식 되면 점등이 됩니다.폭스바겐 차량의 타이어 공기압은 각 바퀴의 회전수를 감지하여, 회전수가 많거나 일정하지 않은 경우에 타이어에 바람이 빠진것으로 인식하여 경고등을 점등 시키게 됩니다. 따라서 공기압의 변동 외에 바퀴의 회전수를 일정하지 않게 하는 요인이 발생할 경우 타이어에 이상이 없어도 경고등이 점등 될 수 있습니다.차량 경고등 확인 하기* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.경고등이 점등된 경우 차량을 정차 한 후 타이어에 이상이 없는지 확인 후 이상이 없을 경우 경고등 리셋을 하실 수 있습니다.자세한 설정법은 아래 링크를 통해 영상으로 확인하세요.타이어 공기압 경고등 조치방법* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.* 공기압 경고등 리셋(재설정) 방법은 차종별, 생산년도별로 상이할 수 있으니 자세한 내용은 반드시 고객님 차량의 사용자 매뉴얼을 참고해 주시고, 증상이 해결되지 않을 경우 폭스바겐 공식 서비스 센터로 연락 후 방문 하시기 바랍니다.'),(3,'차량 기능 & 조작','후진 시 미러다운 기능이 작동되지 않습니다.','사이드미러 조작 스위치를 R에 위치한 상태에서 기어레버를 후진으로 놓으면 설정된 조건에 따라 미러다운 기능이 작동하며, 15km/h 이상의 속도로 전진 주행 하거나, 미러 조작 스위치가 R에서 다른 위치로 바뀌게 되면 원래 위치로 돌아오게 됩니다.미러다운 작동 시 미러의 위치를 설정하고자 할 경우 시동을 켜고 사이드미러 조작 스위치를 R에 위치 시킵니다.안전을 위해 주차브레이크를 켠 상태로 기어레버를 후진으로 놓고 사이드미러 조작 버튼을 조정하여 설정이 가능합니다.자세한 설정법은 아래 링크를 통해 영상으로 확인하세요.후진 시 미러다운 기능 설정법* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(4,'차량 기능 & 조작','차량 스마트 키 리모컨 배터리가 방전되었는데 시동을 걸 수 있는 방법이 없을까요?','방전된 차량의 스마트키 배터리를 교체 하실 수 없는 상황에서는 브레이크 페달을 밟고 스티어링 휠 (차량 핸들) 아래의 컬럼 우측에 키 또는 중앙 센터 콘솔 앞 오목하게 들어간 위치에 차량 키를 올려두고 시동을 걸수 있는 방법이 있습니다.모델별로 조치방법이 다를 수 있으며, 자세한 조치방법은 아래 링크를 통해 영상으로 확인하세요.비상키로 차량 문 열기 & 키 배터리 없을 때 시동걸기* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(5,'차량 기능 & 조작','운전자 보조시스템(ACC, 레인어시스트, 프론트 어시스트, 트래블 어시스트 등)이 가끔 정상적으로 작동하지 않는 경우가 있는데 왜 그런가요?','운전자 보조 시스템은 차량에 부착된 여러 개의 카메라와 센서들이 작동하여 운전자의 편의나 안전을 보조하기 위한 시스템입니다.이러한 보조 시스템은 센서의 오염 상태, 도로의 상황, 기상 상황, 센서의 손상, 물체와의 거리나 각도 등 여러 변수에 따라 영향을 받게 되므로 물리적 한계가 있을 수 있으며 운전자의 조작없이 시스템에만 의존하는 운행은 안전을 보장 할 수 없습니다.따라서 고객님 차량의 사용자 매뉴얼을 통해 각 보조 시스템의 기능과 특성을 잘 이해하고 바른 방법으로 사용 하시기를 당부 드립니다.운전자 보조 시스템의 오작동 발생 빈도가 높은 경우 폭스바겐 공식 서비스 센터로 방문하셔서 점검을 받으시기 바랍니다.보조시스템 사용법에 대한 안내는 아래 영상을 참고해주세요IQ Drive: 운전자 주행 보조시스템* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(6,'소모품 & 정비','요소수 (AdBlue) 는 언제 보충을 하게 되나요? 보충을 하지 않을 경우 어떤 문제가 생기나요?','요소수의 보충 시점은 일정한 주기가 있지는 않습니다.같은 차종이나 동일한 차량이라도 운행 패턴이나 주행 환경에 따라 보충 필요 시점은 많은 차이가 있을 수 있으니 계기판의 메뉴에서 차량의 예상 보충 시점을 확인 하시기 바랍니다. (단, 주행 가능 거리 2,400km 부터 표시가 나타남)요소수 경고등 점등 시 반드시 보충이 필요하며 만약 요소수 레벨이 너무 낮아질 경우 차량의 시동이 불가 (점프 시동을 포함) 하오니 주행거리가 1,000 km가 되기 전에는 반드시 보충을 하시기 바랍니다. 요수수 관련 경고등에 대한 추가 정보는 사용자 매뉴얼이나 My VW 앱 내의 경고등 안내 페이지를 확인 하세요. 차량 경고등 확인 하기'),(7,'경고등 & 알림','계기판에 \"Inspection\"\" / \"\"Oil Service\"\" / “Service Now”/ “서비스 만료” 와 같은 알림등이 뜨는데 뭔가요?\"','해당 경고등은 차량에 설정된 서비스 주기 또는 엔진오일의 경우 고객님 차량의 오일 상태를 체크하여 정기점검 또는 엔진 오일 서비스 시기를 안내하는 것이며 곧 서비스나 인스펙션이 예정된 경우라면, 시동을 켰을 때 서비스 알림 메시지가 나타나게 됩니다.명시된 킬로미터나 기간은 서비스가 요구되는 시점까지의 주행 거리나 주행 기간을 의미하는 것입니다. 따라서 잔여 기간이나 주행거리가 만료 되기 전에 폭스바겐 공식 서비스 센터로 방문하여 서비스를 받으시기 바랍니다.폭스바겐에서는 편리한 예약 서비스를 위해 My VW 앱을 통해 소모성 정비에 대한 온라인 예약 서비스를 제공하고 있습니다.온라인 서비스 예약 바로가기* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(8,'소모품 & 정비','소모품 주기표 상에 있는 교환 주기에 맞춰서 서비스를 받으면 되나요? 필터와 같은 일부 서비스의 교환 주기는 너무 긴 것 같습니다.','국내시장에 판매되는 차량의 소모품 권장 교체 주기는 사용되는 각 소모품들의 제품 사양에 따라 유럽시장 기준으로 일반적인 운행조건하에서 서비스가 필요한 조건으로 반영되어 안내가 되고 있습니다.권장 교체 서비스 주기는 각 소모품들의 사용가능한 한계 수명으로 보시면 되며 국가 또는 지역별 주행 환경이나 운전자의 운행 방식 그리고 고객님들의 필요에 따라 일부 서비스는 권장 주기보다 미리 실시될 수도 있습니다. 예를 들어 먼지가 많은 계절이나 장마철과 같이 비가 많이 오는 동안에는 공기정화 필터와 와이퍼를 미리 교체하시면 쾌적하고 안전한 운행을 하시는데 더욱 도움이 될 수 있습니다.'),(9,'차량 기능 & 조작','비 오는 날, 후진 시 물체가 없는데도 파킹 센서 부저가  울릴 때가 있습니다. 왜 그런가요?','파킹 센서는 초음파센서로서 센서 부위에 맺힌 빗방울을 물체로 인식하여 경고음이 작동될 때가 간혹 있습니다. 이것은 일시적인 현상이며, 센서 부위에 빗방울이 제거되면 다시 정상적으로 작동됩니다.'),(10,'소모품 & 정비','에어컨을 작동시키거나 끄면 악취가 납니다.','에어컨 사용 시 발생하는 물이 다 배출되지 않고 에어컨 증발기에 남아 곰팡이가 발생하여 나는 냄새입니다. 예방을 위해서는 평소에 에어컨을 사용하고 시동을 끄기 몇 분 전에 에어컨(A/C버튼)을 끄고 송풍을 해 주시면 에어컨 내부가 건조되어 곰팡이의 번식을 억제할 수 있습니다. 아울러 실내 공기 정화 필터를 주기적으로 교환해 주는 것이 좋습니다.일단 곰팡이가 발생하면 에어컨 증발기를 깨끗이 청소하는 것이 가장 확실한 방법이므로 폭스바겐 공식 서비스 센터에 방문하셔서 서비스를 받으실 것을 권장 드립니다.폭스바겐에서는 편리한 예약 서비스를 위해 My VW 앱을 통해 소모성 부품 정비에 대한 온라인 예약 서비스를 제공하고 있습니다.온라인 서비스 예약 바로가기* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(11,'경고등 & 알림','워셔액을 보충했는데 경고등이 안 없어집니다.','시중에 유통 되고 있는 워셔액 중 폭스바겐 차량의 워셔액 레벨 센서의 작동에 장애를 일으킬 수 있는 제품을 사용하실 경우 발생 할 수 있습니다. (예. 발수 코팅제가 포함 된 워셔액)예방을 위해서 폭스바겐 정품 워셔액의 사용을 권장 드리며, 해당 증상 발생 시 폭스바겐 공식 서비스 센터 방문 후 점검을 받으시기 바랍니다.워셔액 보충 방법이 궁금하시다면 아래 링크를 통해 영상으로 확인해보세요.워셔액 경고등 점등 시 조치방법* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(12,'차량 기능 & 조작','비가 많이 오는데 사이드 미러 열선이 작동 안되는데 어떤 조건에서 작동이 되나요?','사이드 미러의 열선은 외부 온도가 일정 온도 이하로 내려가지 않으면 열선이 켜져 있어도 작동되지 않습니다.일반적으로 외부 온도가 +20 °C 아래로 내려갈 때 작동이 되도록 설정되어 있으며 처음에는 최고 출력으로 작동 되고, 약 2분이 지나면, 주위 온도 수준을 고려해서 히터가 작동됩니다.세부적인 작동 조건은 차량 모델마다 상이 할 수 있으니 보유하신 모델의 사용자 매뉴얼을 확인 하시기 바랍니다.'),(13,'차량 기능 & 조작','이중 주차 시 기어를 중립에 두고 내리려고 하면 키가 안 빠지거나, 차 문이 잠기지 않습니다.','폭스바겐 차량은 고객님과 차량의 안전을 위해 중립 위치에서는 주차가 되지 않습니다. 반드시 P 위치에 두시고 주차 하시기 바랍니다.'),(14,'차량 기능 & 조작','세차를 할 때 와이퍼를 들어 올린 후 전면 유리를 닦으려고 하면  와이퍼가 차량 후드에 걸려 올라가지 않아 불편합니다.','세차 시 와이퍼를 들어 올리고자 하실 때에는 아래의 방법으로 와이퍼를 먼저 서비스 위치로 이동시켜야 합니다.1) 서비스 위치 활성화엔진 후드가 닫혀 있는 상태에서 시동 스위치를 잠시 켰다가 끈 후 와이퍼 작동 레버를 아래 방향으로 누릅니다. 앞 유리 와이퍼가 ‘서비스 위치’로 이동 하게 됩니다.2) 서비스 위치 비활성화 (원래 위치로 이동)엔진 후드가 닫혀 있고 시동 스위치가 켜진 상태에서 와이퍼 레버를 아래쪽으로 살짝 누르게 되면, 다시 초기 위치로 되돌릴 수 있습니다.보다 자세한 내용은 고객님 차량의 사용자 매뉴얼을 확인해 주시기 바랍니다.'),(15,'소모품 & 정비','혼유사고 발생 시 발생할 수 있는 문제는 어떤 것이 있으며,  어떻게 조치해야 하나요?','혼유는 엔진 연료 계통 및 엔진 구성 부품에 치명적인 손상을 일으킬 수 있습니다. 따라서 주유 시 꼭 해당 연료를 주유원에게 말씀하여 주시기 바랍니다. 혼유 사고 발생 시에는 엔진 시동을 걸지 마시고, 가까운 폭스바겐 공식 서비스센터로 견인 조치 하셔야 더 큰 손상을 막을 수 있습니다.'),(16,'경고등 & 알림','제 차는 TDI 차량인데 DPF(디젤 미립자 필터)가 장착 되어 있습니다.\n가끔 주행 중에 DPF 경고등이 점등 됐다가 소등되는 이유는 무엇입니까?','DPF(Diesel Particle Filter)는 경유의 연소 시 발생하는 그을음을 걸러 주는 장치로 잦은 단거리 주행을 할 경우 필터에 찬 그을음이 제거되지 않아 경고등이 점등 될 수 있습니다.DPF에 걸러진 매연은 고온이 가해질 경우 연소가 되는데 60km/h 이상의 속도로 30분 이상 주행을 할 경우 제거되어 경고등이 소등 됩니다.상기 설명된 조치로도 경고등이 소등되지 않으면 가까운 폭스바겐 공식 서비스센터에서 점검을 받으시기 바랍니다.'),(17,'소모품 & 정비','전조등(헤드램프)에 습기가 차는 현상은 왜 그런가요?','전조등 내에 뜨거운 열이 환기 통로를 통해 교환될 때, 찬 공기는 전조등 내로 빠르게 유입됩니다. 이 때 전조등 내 가장 차가운 곳부터 응축이 일어날 수 있습니다.이러한 자연 현상으로 인하여 전조등 내에 습기가 차는 현상이 나타날 수 있으나, 전조등의 성능이나 내구성에는 영향이 없습니다. 전조등 내 발생된 습기는 전조등 사용 후 일정시간이 지나면 사라집니다. 단, 전조등의 열이 미치지 않는 부위의 경우에는 천천히 사라질 수 있습니다.'),(18,'차량 기능 & 조작','내비게이션 지도를 업데이트 하려면 서비스센터에 방문을 해야 하나요?','1. MIB3 장착 모델 & 투아렉 2020년식~폭스바겐 공식 홈페이지에서 지도 데이터를 SD카드에 직접 내려 받은 후 SD카드를 차량에 연결하여 업데이트가 가능합니다.2. Ex-box 장착 모델출고 시 장착된 정품 네비게이션은 차량 조수석 시트 하단의 네비게이션 단말장치에 삽입된 SD카드를 탈거하여 \'현대 엠엔소프트\' 홈페이지 (PC 버전만 사용 가능)에서 네비게이션 업데이트가 가능합니다.네비게이션 시리얼 번호는 구매 당시 지급 받으신 차량 설명서를 확인 바랍니다.* 차종별로 SD카드 위치가 다를 수 있어 자세한 사항은 폭스바겐 공식 서비스센터로 문의 바랍니다.* 투아렉 차량의 네비게이션 맵은 상기 방식으로 업데이트가 불가합니다.네비게이션 업데이트 방법에 대한 자세한 내용은 아래 링크를 통해 영상으로 확인하세요.내비게이션 업데이트 (Ex-box 장착 모델)내비게이션 업데이트 (MIB3 장착 모델 & 투아렉 2020년식~)* 모바일에서 원활하게 지원이 되며, My VW 앱을 통해서도 확인하실 수 있습니다.'),(19,'소모품 & 정비','브레이크 오일을 교환해야 되는 이유는 무엇일까요?','브레이크 오일은 수분을 흡수합니다. 사용기간이 경과될수록 수분량이 증가되어 브레이크 시스템을 부식시키거나 수명을 저하시킬 수 있습니다. 이러한 경우 제동 거리가 길어지고 ABS작동에 악영향을 줄수 있습니다.브레이크 오일은 매 2년마다 교환을 하실것을 권장합니다. 폭스바겐 정품 브레이크 오일은 특수 글리콜 기반 구성으로 부식 억제제를 포함하며 표준 DOT-4 제품과 비교하여 큰 작동 신뢰성을 제공합니다.');
/*!40000 ALTER TABLE `volkswagen_faq` ENABLE KEYS */;
UNLOCK TABLES;

