/*!50001 VIEW `view_car_recommend` AS with `base` as (select `c`.`id` AS `car_id`,`s`.`sido_cd` AS `sido_cd`,`s`.`sido_nm` AS `sido_nm`,`c`.`brand` AS `브랜드`,`c`.`car_name` AS `차량명`,`c`.`car_type` AS `차종`,`c`.`fuel_type` AS `연료형태`,`c`.`price_num` AS `출고가`,round(((case when ((`c`.`fuel_type` collate utf8mb4_unicode_ci) = '전기(배터리)') then 350.00 else `p`.`price` end) / cast(replace(replace(replace(`c`.`avg_efficiency`,'㎞/ℓ',''),'㎞/kWh',''),' ','') as decimal(10,2))),2) AS `km당_연료비`,(cast(`v`.`vehicle_count` as decimal(10,2)) / nullif(`ch`.`charger_count`,0)) AS `충전기1대당_전기차수`,`sub`.`total_remaining` AS `보조금_잔여수량`,(case when ((`c`.`car_type` collate utf8mb4_unicode_ci) like '%경차%') then `sub`.`max_subsidy_micro` when (((`c`.`car_type` collate utf8mb4_unicode_ci) like '%트럭%') or ((`c`.`car_type` collate utf8mb4_unicode_ci) like '%픽업%')) then `sub`.`max_subsidy_cargo` else `sub`.`max_subsidy_passenger` end) AS `차종별_지원금` from (((((`car_info` `c` join (select distinct (`sido_oil_price`.`sido_cd` collate utf8mb4_unicode_ci) AS `sido_cd`,(`sido_oil_price`.`sido_nm` collate utf8mb4_unicode_ci) AS `sido_nm` from `sido_oil_price` where ((`sido_oil_price`.`sido_cd` not in ('0','00')) and (`sido_oil_price`.`sido_nm` <> '전국'))) `s`) left join `sido_oil_price` `p` on(((`s`.`sido_cd` = (`p`.`sido_cd` collate utf8mb4_unicode_ci)) and ((((`c`.`fuel_type` collate utf8mb4_unicode_ci) in ('가솔린','하이브리드','LPG+가솔린')) and ((`p`.`prod_cd` collate utf8mb4_unicode_ci) = 'B027')) or (((`c`.`fuel_type` collate utf8mb4_unicode_ci) = '디젤') and ((`p`.`prod_cd` collate utf8mb4_unicode_ci) = 'D047')) or (((`c`.`fuel_type` collate utf8mb4_unicode_ci) = 'LPG') and ((`p`.`prod_cd` collate utf8mb4_unicode_ci) = 'K015')))))) left join (select (`electric_vehicles`.`sido` collate utf8mb4_unicode_ci) AS `sido`,`electric_vehicles`.`vehicle_count` AS `vehicle_count` from `electric_vehicles` where (`electric_vehicles`.`sido` <> '전국')) `v` on((`s`.`sido_nm` = `v`.`sido`))) left join (select (`ev_chargers`.`sido` collate utf8mb4_unicode_ci) AS `sido`,`ev_chargers`.`charger_count` AS `charger_count` from `ev_chargers` where (`ev_chargers`.`sido` <> '전국')) `ch` on((`s`.`sido_nm` = `ch`.`sido`))) left join (select (`electric_car_subsidies`.`sido` collate utf8mb4_unicode_ci) AS `sido`,`electric_car_subsidies`.`total_remaining` AS `total_remaining`,`electric_car_subsidies`.`max_subsidy_passenger` AS `max_subsidy_passenger`,`electric_car_subsidies`.`max_subsidy_micro` AS `max_subsidy_micro`,`electric_car_subsidies`.`max_subsidy_cargo` AS `max_subsidy_cargo` from `electric_car_subsidies` where (`electric_car_subsidies`.`sido` <> '전국')) `sub` on((`s`.`sido_nm` = `sub`.`sido`)))), `calc_price` as (select `base`.`car_id` AS `car_id`,`base`.`sido_cd` AS `sido_cd`,`base`.`sido_nm` AS `sido_nm`,`base`.`브랜드` AS `브랜드`,`base`.`차량명` AS `차량명`,`base`.`차종` AS `차종`,`base`.`연료형태` AS `연료형태`,`base`.`출고가` AS `출고가`,`base`.`km당_연료비` AS `km당_연료비`,`base`.`충전기1대당_전기차수` AS `충전기1대당_전기차수`,`base`.`보조금_잔여수량` AS `보조금_잔여수량`,`base`.`차종별_지원금` AS `차종별_지원금`,(case when ((`base`.`연료형태` collate utf8mb4_unicode_ci) <> '전기(배터리)') then `base`.`출고가` when (((`base`.`연료형태` collate utf8mb4_unicode_ci) = '전기(배터리)') and (`base`.`보조금_잔여수량` > 0)) then (`base`.`출고가` - `base`.`차종별_지원금`) else `base`.`출고가` end) AS `실구매가_금액` from `base`) select `calc_price`.`car_id` AS `car_id`,`calc_price`.`sido_cd` AS `sido_cd`,`calc_price`.`sido_nm` AS `sido_nm`,`calc_price`.`브랜드` AS `브랜드`,`calc_price`.`차량명` AS `차량명`,`calc_price`.`차종` AS `차종`,`calc_price`.`연료형태` AS `연료형태`,`calc_price`.`출고가` AS `출고가`,`calc_price`.`km당_연료비` AS `km당 연료비`,round((5 + (90 * (1 - percent_rank() OVER (ORDER BY `calc_price`.`km당_연료비` ) ))),2) AS `연비점수`,(case when ((`calc_price`.`연료형태` collate utf8mb4_unicode_ci) = '전기(배터리)') then round((5 + (90 * (1 - percent_rank() OVER (PARTITION BY (case when ((`calc_price`.`연료형태` collate utf8mb4_unicode_ci) = '전기(배터리)') then 1 else 0 end) ORDER BY `calc_price`.`충전기1대당_전기차수` ) ))),2) else 100.00 end) AS `인프라 점수`,round((5 + (90 * (1 - percent_rank() OVER (ORDER BY `calc_price`.`실구매가_금액` ) ))),2) AS `실구매가 점수`,(case when ((`calc_price`.`연료형태` collate utf8mb4_unicode_ci) = '전기(배터리)') then concat('충전기당 전기차 수 : ',round(`calc_price`.`충전기1대당_전기차수`,2)) else '해당사항 없음' end) AS `인프라 상황`,(case when ((`calc_price`.`연료형태` collate utf8mb4_unicode_ci) <> '전기(배터리)') then '해당사항 없음' when (((`calc_price`.`연료형태` collate utf8mb4_unicode_ci) = '전기(배터리)') and (`calc_price`.`보조금_잔여수량` > 0)) then cast(`calc_price`.`차종별_지원금` as char charset utf8mb4) else '현재 지자체의 예산이 소진되어 지원금을 받을 수 없습니다' end) AS `지원받은 보조금` from `calc_price` */;
